-- Hunt database schema (Cloudflare D1 / SQLite), generated by crm/scripts/schema.mjs from crm/migrations (22 files).
-- Do not edit: add a migration, then run `node scripts/schema.mjs` in crm/. Timestamps are ISO-8601 UTC strings; JSON columns hold TEXT.

CREATE TABLE access (
  user_id     TEXT PRIMARY KEY REFERENCES users(id),
  tg_status   TEXT NOT NULL DEFAULT 'off',   -- off | on | rights (more rights than needed: nothing is read) | revoking (we stopped, waiting for the person to remove the bot)
  tg_conn     TEXT,                          -- Telegram's business connection id
  tg_extra    TEXT NOT NULL DEFAULT '[]',    -- JSON: rights that are too much
  tg_mode     TEXT,                          -- new | only: what the person said they picked (Telegram does not tell the bot)
  wa_status   TEXT NOT NULL DEFAULT 'off',   -- off | button
  dropped     INTEGER NOT NULL DEFAULT 0,    -- messages of people who are not owners: thrown away unread
  retain_days INTEGER NOT NULL DEFAULT 30,   -- conversations go this many days after a project is closed
  ai_cap      REAL,                          -- dollars per project for the server's assistant
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE access_log (
  user_id     TEXT NOT NULL REFERENCES users(id),  -- whose conversations
  actor       TEXT NOT NULL,                       -- users.id
  via         TEXT NOT NULL,                       -- app | agent
  day         TEXT NOT NULL,
  PRIMARY KEY (user_id, actor, via, day)
);

CREATE TABLE access_mutes (
  user_id     TEXT NOT NULL REFERENCES users(id),
  contact_id  TEXT NOT NULL REFERENCES contacts(id),
  PRIMARY KEY (user_id, contact_id)
);

CREATE TABLE access_peers (
  user_id     TEXT NOT NULL REFERENCES users(id),
  contact_id  TEXT NOT NULL REFERENCES contacts(id),
  chat_id     INTEGER NOT NULL,
  last_in_at  TEXT,
  PRIMARY KEY (user_id, contact_id)
);

CREATE TABLE access_receipts (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id),
  data        TEXT NOT NULL,                       -- JSON: what was revoked and deleted, never the texts
  at          TEXT NOT NULL
);

CREATE TABLE afisha (
  id              TEXT PRIMARY KEY,          -- 'ev_' + random
  country         TEXT NOT NULL,             -- pack slug: bali | kz | th
  city            TEXT,                      -- sub-pack slug or NULL
  area            TEXT,                      -- districts.yaml area id, if known
  title           TEXT NOT NULL,
  title_en        TEXT,
  about_ru        TEXT,                      -- one human line in Russian
  about_en        TEXT,
  category        TEXT NOT NULL,             -- culture | nature | sport | dance | music | food | workshop | party | wellness | kids | other | bar | club | beach_club | social_sport | meetup | quiz
  topic           TEXT,                      -- fine slug (kecak, snorkel, padel, …): photo effect and "why" lines
  starts_at       TEXT,                      -- local ISO with offset; NULL for recurring events without a first date
  ends_at         TEXT,
  recurrence      TEXT,                      -- JSON {freq: daily|weekly|monthly|seasonal, time, end?, weekdays?, day?, nth?, months?, from?, until?}
  place_name      TEXT,
  place_id        TEXT,                      -- 'b:<pack place id>' or a places.id
  lat             REAL,
  lng             REAL,
  map_url         TEXT,
  price_kind      TEXT NOT NULL DEFAULT 'unknown', -- free | paid | on_site | unknown
  price           INTEGER,                   -- main units, per person
  currency        TEXT,
  price_note      TEXT,
  entry           TEXT,                      -- free | fee | min_spend | guest_list (nightlife)
  lang            TEXT,                      -- ru | en | id | mixed | none
  booking         TEXT NOT NULL DEFAULT 'none', -- none | message | ticket
  ticket_url      TEXT,
  organizer_name  TEXT,
  organizer_channel TEXT,                    -- telegram | whatsapp | instagram | facebook | email | phone | web
  organizer_address TEXT,
  organizer_contact_id TEXT REFERENCES contacts(id),
  organizer_lang  TEXT,
  source_kind     TEXT,                      -- telegram | instagram | facebook | web | place | pack | user
  source_url      TEXT,
  source_name     TEXT,
  source_rep      REAL,                      -- 0..1 reputation of the source
  sources         TEXT,                      -- JSON [{kind, url, name}] (merged duplicates)
  photo_url       TEXT,                      -- only when the source allows reuse
  photo_credit    TEXT,
  photo_source_url TEXT,
  photo_score     REAL,                      -- 0..1 from the agent's quality gate
  age_min         INTEGER,                   -- 18 | 21
  dress_code      TEXT,
  vibe            TEXT,                      -- chill | party | sport | meet
  crowd           TEXT,                      -- expats | locals | mixed
  beginner        INTEGER,                   -- 1 = beginner-friendly
  outdoor         INTEGER,
  sea             INTEGER,                   -- 1 = needs a calm sea (snorkel, boat)
  tags            TEXT,                      -- JSON [audience signals]
  quality         REAL,                      -- 0..1 agent hint (venue activity, reviews)
  status          TEXT NOT NULL DEFAULT 'active', -- active | cancelled | hidden
  search_id       TEXT REFERENCES searches(id), -- the search it was collected for (informational)
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
, photo_stale_at TEXT, photo_fail TEXT);

CREATE TABLE ai_usage (
  id          TEXT PRIMARY KEY,
  search_id   TEXT NOT NULL REFERENCES searches(id),
  kind        TEXT NOT NULL,                       -- chat | listing | lease | other
  usd         REAL NOT NULL,
  at          TEXT NOT NULL
);

CREATE TABLE bikes (
  id            TEXT PRIMARY KEY,          -- 'bk_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  model         TEXT NOT NULL,
  plate         TEXT,
  rider_id      TEXT REFERENCES users(id), -- NULL = shared
  price         INTEGER,
  currency      TEXT,
  period        TEXT NOT NULL DEFAULT 'month', -- month | week | day
  paid_until    TEXT,                      -- YYYY-MM-DD
  deposit       TEXT,                      -- what was left: "passport copy", "1 000 000 IDR" (never the original passport, never numbers)
  rental_name   TEXT,
  channel       TEXT,                      -- whatsapp | telegram | phone
  address       TEXT,                      -- number or @handle
  phone         TEXT,
  checklist     TEXT,                      -- JSON {video|helmets|stnk|fuel: {done, note}}
  status        TEXT NOT NULL DEFAULT 'active', -- active | returned
  date_from     TEXT,
  return_date   TEXT,
  note          TEXT,
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE bot_state (
  tg_user_id    INTEGER PRIMARY KEY,
  state         TEXT NOT NULL,             -- JSON {kind:'edit_draft', draft_id}
  at            TEXT NOT NULL
);

CREATE TABLE chat_keys (
  owner_id    TEXT PRIMARY KEY REFERENCES users(id),
  kid         TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE "contact_channels" (
  contact_id    TEXT NOT NULL REFERENCES contacts(id),
  channel       TEXT NOT NULL,
  address       TEXT NOT NULL,
  display       TEXT,
  PRIMARY KEY (contact_id, channel, address)
);

CREATE TABLE contacts (
  id            TEXT PRIMARY KEY,          -- 'c_' + random
  name          TEXT,
  role          TEXT,                      -- owner | agent | agency | manager | relative | tenant_subletting
  lang          TEXT,                      -- language we write to them in (en, ru, id, th, kk)
  notes         TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, owner_id TEXT);

CREATE TABLE counters (
  key   TEXT PRIMARY KEY,
  n     INTEGER NOT NULL DEFAULT 0,
  at    TEXT NOT NULL
);

CREATE TABLE deal_terms (
  id            TEXT PRIMARY KEY,          -- 'dt_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  seq           INTEGER NOT NULL,          -- 2, 3, …
  kind          TEXT,                      -- lease | sublease
  date_from     TEXT NOT NULL,             -- YYYY-MM-DD
  date_to       TEXT,                      -- YYYY-MM-DD
  rent          INTEGER,                   -- per month, main units
  currency      TEXT,
  deposit       INTEGER,                   -- the new deposit of this term
  deposit_prev  TEXT,                      -- what happened to the previous term's deposit: returned | carried | pending | kept
  deposit_prev_amount INTEGER,             -- returned / carried amount (main units)
  landlord      TEXT,                      -- name only ("Made, owner"), never ID numbers
  landlord_contact_id TEXT REFERENCES contacts(id),
  status        TEXT NOT NULL DEFAULT 'draft', -- draft | signed | active | ended
  dates         TEXT,                      -- JSON [DealDate] (payments, notice, move-out, deposit return) of this term
  checklist     TEXT,                      -- JSON [{text, done}]
  note          TEXT,
  created_by    TEXT NOT NULL,             -- user id or 'agent'
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  UNIQUE (search_id, seq)
);

CREATE TABLE deals (
  listing_id    TEXT PRIMARY KEY REFERENCES listings(id),
  search_id     TEXT NOT NULL REFERENCES searches(id),
  data          TEXT NOT NULL DEFAULT '{}',-- JSON: terms, payments[], deposit{}, checklist{}, contract_versions[] (no passport data)
  updated_at    TEXT NOT NULL
, asked INTEGER, agreed INTEGER, deal_at TEXT);

CREATE TABLE directory (
  id            TEXT PRIMARY KEY,          -- 'dr_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  grp           TEXT NOT NULL DEFAULT 'services', -- home | bikes | food | services | health | <custom key>
  name          TEXT NOT NULL,
  subtitle      TEXT,                      -- price / hours / "delivers home"
  channel       TEXT,                      -- whatsapp | telegram | phone | map
  address       TEXT,                      -- number or @handle for the channel
  phone         TEXT,                      -- for the call button (whatsapp entries call the same number)
  map_url       TEXT,
  lat           REAL,
  lng           REAL,
  icon          TEXT,
  sort          INTEGER NOT NULL DEFAULT 0,
  created_by    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE documents (
  id            TEXT PRIMARY KEY,          -- 'doc_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  kind          TEXT NOT NULL DEFAULT 'other', -- lease | receipt | owner_consent | movein_video | other
  title         TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'have', -- have | request | due
  due_date      TEXT,                      -- YYYY-MM-DD for status due
  version       INTEGER,
  doc_date      TEXT,                      -- date of this version (YYYY-MM-DD)
  signed_at     TEXT,                      -- YYYY-MM-DD
  pages         INTEGER,
  note          TEXT,                      -- one line under the title
  summary       TEXT,                      -- JSON {sections:[{icon, title, text}], changes, changes_from} (no ID/card numbers)
  tg_file_id    TEXT,
  tg_chat_id    INTEGER,
  file_kind     TEXT,                      -- document | photo | video
  file_name     TEXT,
  mime          TEXT,
  size          INTEGER,
  created_by    TEXT,                      -- user id or 'agent'
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, term_seq INTEGER);

CREATE TABLE dossier_items (
  id            TEXT PRIMARY KEY,          -- 'di_' + random
  dossier_id    TEXT NOT NULL REFERENCES dossiers(id),
  kind          TEXT NOT NULL DEFAULT 'other', -- issue | power | cleaning | conflict | good | money | other
  title         TEXT NOT NULL,
  text          TEXT,
  sentiment     INTEGER NOT NULL DEFAULT 0,
  date          TEXT,
  search_id     TEXT REFERENCES searches(id),
  author        TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE dossiers (
  id            TEXT PRIMARY KEY,          -- 'ds_' + random
  title         TEXT NOT NULL,
  area_text     TEXT,
  lat           REAL,
  lng           REAL,
  owner_contact_id TEXT REFERENCES contacts(id),
  owner_identity TEXT,                     -- normalized identity of the owner ('phone:+62…')
  listing_ids   TEXT,                      -- JSON [listing ids] across searches
  verdict_title TEXT,
  verdict       TEXT,
  stats         TEXT,                      -- JSON {months, price, currency, price_note, issues}
  updated_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, owner_id TEXT);

CREATE TABLE drafts (
  id            TEXT PRIMARY KEY,          -- 'd_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  contact_id    TEXT REFERENCES contacts(id),
  listing_id    TEXT REFERENCES listings(id),
  channel       TEXT NOT NULL,
  address       TEXT NOT NULL,
  text          TEXT NOT NULL,
  kind          TEXT NOT NULL DEFAULT 'other', -- first_contact | follow_up | negotiate | schedule | running_late | decline | cancel | found | reply | other
  reason        TEXT,                      -- why the agent wants to send it, shown to the approver
  status        TEXT NOT NULL DEFAULT 'pending', -- pending | approved | edited | rejected | sent | failed
  edited_text   TEXT,
  decided_by    TEXT REFERENCES users(id),
  tg_message_id INTEGER,                   -- approval message in the owner's DM with the bot
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, requested_by TEXT, tr TEXT);

CREATE TABLE event_bookings (
  id              TEXT PRIMARY KEY,          -- 'eb_' + random
  event_id        TEXT NOT NULL REFERENCES afisha(id),
  search_id       TEXT NOT NULL REFERENCES searches(id),
  occ             TEXT NOT NULL,             -- YYYY-MM-DD
  starts_at       TEXT NOT NULL,             -- local ISO with offset of that occurrence
  who             TEXT NOT NULL,             -- JSON [user ids]
  guests          INTEGER NOT NULL DEFAULT 0,
  kind            TEXT NOT NULL DEFAULT 'join', -- join | guest_list | table | slot
  note            TEXT,
  status          TEXT NOT NULL DEFAULT 'requested', -- requested | drafted | asked | booked | declined | cancelled | attended
  draft_id        TEXT REFERENCES drafts(id),
  requested_by    TEXT NOT NULL REFERENCES users(id),
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

CREATE TABLE event_feedback (
  event_id        TEXT NOT NULL REFERENCES afisha(id),
  user_id         TEXT NOT NULL REFERENCES users(id),
  search_id       TEXT NOT NULL REFERENCES searches(id),
  occ             TEXT,                      -- YYYY-MM-DD of the occurrence acted on last
  liked           INTEGER NOT NULL DEFAULT 0,
  nope            INTEGER NOT NULL DEFAULT 0,
  want            INTEGER NOT NULL DEFAULT 0,
  bookmark        INTEGER NOT NULL DEFAULT 0,
  attended        INTEGER NOT NULL DEFAULT 0,
  rating          INTEGER,                   -- 1..5 after attending
  category        TEXT,
  topic           TEXT,
  organizer_key   TEXT,
  place_key       TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL, note TEXT,
  PRIMARY KEY (event_id, user_id, search_id)
);

CREATE TABLE events (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  search_id     TEXT REFERENCES searches(id),
  kind          TEXT NOT NULL,             -- vote | draft_decided | listing_added | message_in | viewing_changed | note
  ref           TEXT,                      -- listing/draft/viewing id
  actor         TEXT,                      -- user id or 'agent'
  data          TEXT NOT NULL DEFAULT '{}',
  at            TEXT NOT NULL
);

CREATE TABLE expenses (
  id            TEXT PRIMARY KEY,          -- 'x_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  title         TEXT NOT NULL,
  amount        INTEGER NOT NULL,
  currency      TEXT NOT NULL,
  date          TEXT NOT NULL,             -- YYYY-MM-DD (local)
  paid_by       TEXT NOT NULL REFERENCES users(id),
  split         TEXT,                      -- JSON {user_id: weight}; NULL = searches.shares
  kind          TEXT NOT NULL DEFAULT 'other', -- rent | deposit | power | water | internet | cleaning | pool | repair | food | transport | other
  method        TEXT,                      -- cash | transfer | card
  note          TEXT,
  receipt       TEXT,                      -- KV key of a receipt photo ('r/<search>/<user>-<ts>')
  created_by    TEXT NOT NULL,             -- user id or 'agent'
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, order_id TEXT);

CREATE TABLE guests (
  search_id     TEXT NOT NULL REFERENCES searches(id),
  user_id       TEXT NOT NULL REFERENCES users(id),
  invited_by    TEXT REFERENCES users(id),
  date_from     TEXT NOT NULL,             -- YYYY-MM-DD (access opens 3 days before)
  date_to       TEXT NOT NULL,             -- YYYY-MM-DD (access ends after this day, search timezone)
  areas         TEXT NOT NULL,             -- JSON {guide, places, contacts, issues}
  animal        TEXT,
  status        TEXT NOT NULL DEFAULT 'active', -- active | revoked | expired
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  PRIMARY KEY (search_id, user_id)
);

CREATE TABLE guides (
  search_id     TEXT PRIMARY KEY REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  token_hash    TEXT UNIQUE,
  version       INTEGER NOT NULL DEFAULT 0,
  address       TEXT,
  map_url       TEXT,
  wifi_name     TEXT,
  wifi_password TEXT,                      -- visible to members, guests with the guide area and on the guide page only
  rules         TEXT,                      -- JSON [{icon, text}]
  note          TEXT,
  host_user_id  TEXT REFERENCES users(id), -- the member who shared the link: their name/Telegram is the hosts' contact
  updated_by    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE house_contacts (
  id            TEXT PRIMARY KEY,          -- 'hc_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  contact_id    TEXT REFERENCES contacts(id),
  name          TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'other', -- owner | manager | cleaning | pool | garden | repair | security | internet | other
  note          TEXT,                      -- "repairs at his cost"
  cost          INTEGER,
  currency      TEXT,
  period        TEXT,                      -- month | week | visit | once
  payer         TEXT,                      -- rent (included in the rent) | us
  schedule      TEXT,                      -- "Tue, Fri"
  channel       TEXT,                      -- whatsapp | telegram | phone | ...
  address       TEXT,
  sort          INTEGER NOT NULL DEFAULT 0,
  updated_at    TEXT NOT NULL
);

CREATE TABLE hunters (
  user_id       TEXT PRIMARY KEY REFERENCES users(id),
  is_admin      INTEGER NOT NULL DEFAULT 0, -- admins can invite hunters
  invited_by    TEXT REFERENCES users(id),
  created_at    TEXT NOT NULL
);

CREATE TABLE invites (
  code          TEXT PRIMARY KEY,          -- random, used in the start parameter
  kind          TEXT NOT NULL,             -- hunter | member
  search_id     TEXT REFERENCES searches(id), -- for kind=member
  created_by    TEXT NOT NULL REFERENCES users(id),
  max_uses      INTEGER NOT NULL DEFAULT 1,
  uses          INTEGER NOT NULL DEFAULT 0,
  expires_at    TEXT,
  created_at    TEXT NOT NULL
, data TEXT);

CREATE TABLE isochrones (
  listing_id    TEXT PRIMARY KEY REFERENCES listings(id),
  costing       TEXT NOT NULL,
  rush          REAL,
  geo           TEXT NOT NULL,
  at            TEXT NOT NULL
, rings TEXT);

CREATE TABLE issues (
  id            TEXT PRIMARY KEY,          -- 'is_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  title         TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'open', -- open | scheduled | fixed
  note          TEXT,                      -- what the agent did ("wrote to Made in Indonesian")
  scheduled_at  TEXT,                      -- when the repair is booked (ISO with offset)
  fixed_at      TEXT,
  reported_by   TEXT,                      -- user id or 'agent'
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE items (
  id            TEXT PRIMARY KEY,          -- 'it_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  name          TEXT NOT NULL,
  price         INTEGER,
  currency      TEXT,
  seller        TEXT,                      -- "Наталья" (from whom)
  bought_at     TEXT,                      -- YYYY-MM-DD
  photo         TEXT,                      -- KV key 'i/<search>/<user>-<ts>'
  icon          TEXT,
  status        TEXT NOT NULL DEFAULT 'have', -- have | offered | sold
  sold_price    INTEGER,
  resale_target INTEGER,
  note          TEXT,
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE listing_contacts (
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  contact_id    TEXT NOT NULL REFERENCES contacts(id),
  role          TEXT,                      -- primary | secondary
  PRIMARY KEY (listing_id, contact_id)
);

CREATE TABLE listings (
  id            TEXT PRIMARY KEY,          -- stable slug from source: 'fb-1722243245987208', 'krisha-12345'
  search_id     TEXT NOT NULL REFERENCES searches(id),
  title         TEXT NOT NULL,
  district      TEXT,                      -- district slug from the region pack
  area_text     TEXT,                      -- free text as the source says it
  lat           REAL,
  lng           REAL,
  map_url       TEXT,
  property_type TEXT,                      -- villa | house | apartment | condo | townhouse | room
  bedrooms      INTEGER,
  bathrooms     INTEGER,
  size_m2       REAL,
  price         INTEGER,                   -- per month, local currency, main units
  currency      TEXT,
  price_note    TEXT,                      -- "22M + electricity, was 27"
  includes      TEXT,                      -- JSON array: ["wifi","water","cleaning"]
  available     TEXT,                      -- "from 2026-11-23" or "23.11–31.03"
  fields        TEXT NOT NULL DEFAULT '{}',-- JSON, region pack listing_fields (living_room, pool…)
  photos        TEXT NOT NULL DEFAULT '[]',-- JSON array of {file_id, w, h}: Telegram file_id is the storage
  source        TEXT,                      -- 'facebook_group', 'krisha', 'telegram', 'agent'
  source_url    TEXT,
  summary       TEXT,                      -- agent's 1–3 line take for humans
  status        TEXT NOT NULL DEFAULT 'new', -- new | contacted | talking | needs_you | viewing | rejected | taken | closed
  next_step     TEXT,                      -- what happens next, human readable
  decision      TEXT,                      -- want_view | thinking | not_interested | take (set by humans)
  decided_by    TEXT REFERENCES users(id),
  decided_at    TEXT,
  tg_message_id INTEGER,                   -- card message in the search chat
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, checks TEXT, travel TEXT, location TEXT, flood TEXT, short_name TEXT);

CREATE TABLE members (
  search_id     TEXT NOT NULL REFERENCES searches(id),
  user_id       TEXT NOT NULL REFERENCES users(id),
  role          TEXT NOT NULL DEFAULT 'member', -- owner | member | viewer
  notify        INTEGER NOT NULL DEFAULT 1, animal TEXT, reveal_seen_at TEXT, digest INTEGER NOT NULL DEFAULT 1, visa_until TEXT, surf INTEGER, nightlife INTEGER, afisha INTEGER, taste TEXT,
  PRIMARY KEY (search_id, user_id)
);

CREATE TABLE messages (
  id            TEXT PRIMARY KEY,          -- 'm_' + random
  search_id     TEXT REFERENCES searches(id),
  contact_id    TEXT REFERENCES contacts(id),
  listing_id    TEXT REFERENCES listings(id),
  channel       TEXT NOT NULL,
  direction     TEXT NOT NULL,             -- in | out | call_missed
  text          TEXT,
  media         TEXT NOT NULL DEFAULT '[]',-- JSON array of {type, key|url, caption}
  external_id   TEXT,                      -- id in the channel, for dedupe
  at            TEXT NOT NULL, tr TEXT,
  UNIQUE (channel, external_id)
);

CREATE TABLE meter_readings (
  id            TEXT PRIMARY KEY,          -- 'mr_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  kind          TEXT NOT NULL DEFAULT 'reading', -- reading | topup | photo (a member's photo waiting for the agent)
  kwh           REAL,                      -- reading: balance left; topup: kWh bought
  amount        INTEGER,                   -- topup: money paid (main units)
  currency      TEXT,
  photo         TEXT,                      -- KV key 'm/<search>/<user>-<ts>'
  note          TEXT,
  at            TEXT NOT NULL,             -- when the meter showed this (ISO)
  created_by    TEXT NOT NULL,             -- user id or 'agent'
  created_at    TEXT NOT NULL
);

CREATE TABLE moveouts (
  search_id     TEXT PRIMARY KEY REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  date          TEXT,                      -- YYYY-MM-DD
  steps         TEXT,                      -- JSON {notice|keys|video|cleaning|deposit: {status: done|wait|todo|info, note, date?, at?, channel?}}
  pushback      TEXT,                      -- JSON {who, contact_id?, quote, points} the agent's talking points
  updated_at    TEXT NOT NULL
);

CREATE TABLE order_lines (
  order_id      TEXT NOT NULL REFERENCES orders(id),
  item_id       TEXT NOT NULL REFERENCES supplier_items(id),
  qty           REAL NOT NULL,
  added_by      TEXT NOT NULL,
  price         INTEGER,                       -- snapshot when the order left the basket (a basket uses the live price)
  price_unsure  INTEGER,
  name_id       TEXT,                          -- snapshots too: an old receipt never changes
  name_ru       TEXT,
  name_en       TEXT,
  at            TEXT NOT NULL,
  PRIMARY KEY (order_id, item_id)
);

CREATE TABLE order_set_lines (
  set_id        TEXT NOT NULL REFERENCES order_sets(id),
  item_id       TEXT NOT NULL REFERENCES supplier_items(id),
  qty           REAL NOT NULL,
  sort          INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (set_id, item_id)
);

CREATE TABLE order_sets (
  id            TEXT PRIMARY KEY,              -- 'os_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  supplier_id   TEXT NOT NULL REFERENCES suppliers(id),
  name          TEXT NOT NULL,                 -- ≤ 40 characters
  name_key      TEXT NOT NULL,                 -- lower-cased, ё → е, spaces folded: unique per search
  repeat        TEXT NOT NULL DEFAULT 'none',  -- none | weekly | biweekly
  days          INTEGER NOT NULL DEFAULT 0,    -- weekdays bitmask: 1 = Monday … 64 = Sunday
  time          TEXT NOT NULL DEFAULT '09:00', -- HH:MM in the search's time zone
  anchor        TEXT,                          -- biweekly: the Monday (YYYY-MM-DD) of a week that fires
  last_sent     TEXT,                          -- the local day ('YYYY-MM-DD') of the last reminder: once per occurrence
  skipped       TEXT,                          -- the last occurrence somebody skipped ('YYYY-MM-DD')
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE orders (
  id            TEXT PRIMARY KEY,              -- 'or_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  supplier_id   TEXT NOT NULL REFERENCES suppliers(id),
  status        TEXT NOT NULL DEFAULT 'basket',
  via           TEXT,                          -- whatsapp | telegram | agent
  draft_id      TEXT,
  deliver_day   TEXT,                          -- YYYY-MM-DD local
  deliver_time  TEXT,                          -- HH:MM
  note          TEXT,
  with_address  INTEGER,                       -- NULL = default (on for the first order to the supplier)
  text          TEXT,                          -- the message as it went out
  total_est     INTEGER,                       -- priced lines at the moment of sending
  unknown_n     INTEGER,                       -- lines without a price
  total_final   INTEGER,                       -- what the supplier said / what was paid
  reply         TEXT,                          -- the supplier's answer (agent)
  reply_tr      TEXT,
  opened_at     TEXT,
  sent_at       TEXT,
  sent_by       TEXT,
  confirmed_at  TEXT,
  confirmed_by  TEXT,                          -- user id or 'agent'
  delivered_at  TEXT,
  paid_by       TEXT,
  expense_id    TEXT,
  cancelled_at  TEXT,
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, cleared TEXT, cleared_at TEXT);

CREATE TABLE outbox (
  key           TEXT PRIMARY KEY,
  chat_id       INTEGER NOT NULL,
  payload       TEXT NOT NULL,             -- JSON {kind:'text', text, reply_markup?} | {kind:'draft', draft_id}
  not_before    TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE pack_shares (
  id          TEXT PRIMARY KEY,                -- 'shr_' + random, also the ref in the registry
  user_id     TEXT NOT NULL REFERENCES users(id),
  country     TEXT NOT NULL,
  title       TEXT NOT NULL,
  digest      TEXT NOT NULL,                   -- sha256 of the payload: the same content is asked about once
  payload     TEXT,                            -- JSON {note, author, base, files, sources}; NULL after the decision
  status      TEXT NOT NULL,                   -- asked | declined | off | sent | returned | rejected | approved | merged
  comment     TEXT,
  remote_id   TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE parties (
  id              TEXT PRIMARY KEY,          -- 'pt_' + random
  search_id       TEXT NOT NULL REFERENCES searches(id),
  title           TEXT NOT NULL,
  starts_at       TEXT NOT NULL,             -- local ISO with offset
  ends_at         TEXT,
  theme           TEXT,
  vibe            TEXT,                      -- chill | dance | dinner | pool | games | sunset
  dress_code      TEXT,
  capacity        INTEGER,                   -- heads incl. +1s; NULL = no limit
  plus_one        INTEGER NOT NULL DEFAULT 1,
  byob            INTEGER,                   -- 1 = bring your own drinks, 0 = we have drinks, NULL = not said
  note            TEXT,
  address         TEXT,                      -- shown only to "going" guests on their personal link
  how_to          TEXT,                      -- how to get there (same)
  wifi            INTEGER NOT NULL DEFAULT 0, -- 1 = show the house guide's Wi-Fi to "going" guests
  cover           TEXT,                      -- KV key 'y/<id>/c-<ts>' or NULL (= the home's first photo)
  photos          TEXT,                      -- JSON [{kv, by, at}] after the party
  token_hash      TEXT,
  token_ver       INTEGER NOT NULL DEFAULT 1,
  status          TEXT NOT NULL DEFAULT 'active', -- active | cancelled | done
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

CREATE TABLE party_guests (
  id              TEXT PRIMARY KEY,          -- 'pg_' + random
  party_id        TEXT NOT NULL REFERENCES parties(id),
  name            TEXT NOT NULL,
  answer          TEXT NOT NULL,             -- going | maybe | no
  plus_one        INTEGER NOT NULL DEFAULT 0,
  secret_hash     TEXT NOT NULL,
  removed         INTEGER NOT NULL DEFAULT 0, -- a member removed the guest (their link stops working)
  came            INTEGER,                   -- after the party: 1 / 0 / NULL
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

CREATE TABLE party_items (
  id              TEXT PRIMARY KEY,          -- 'pi_' + random
  party_id        TEXT NOT NULL REFERENCES parties(id),
  title           TEXT NOT NULL,
  kind            TEXT NOT NULL DEFAULT 'other', -- drinks | ice | food | music | cups | cleanup | other
  who             TEXT REFERENCES users(id),
  cost            INTEGER,
  currency        TEXT,
  done            INTEGER NOT NULL DEFAULT 0,
  expense_id      TEXT,
  sort            INTEGER NOT NULL DEFAULT 0,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);

CREATE TABLE party_ratings (
  party_id        TEXT NOT NULL REFERENCES parties(id),
  user_id         TEXT NOT NULL REFERENCES users(id),
  rating          INTEGER NOT NULL,          -- 1..5
  note            TEXT,
  at              TEXT NOT NULL,
  PRIMARY KEY (party_id, user_id)
);

CREATE TABLE people_notes (
  id            TEXT PRIMARY KEY,          -- 'pn_' + random
  identity      TEXT NOT NULL,
  contact_id    TEXT REFERENCES contacts(id),
  search_id     TEXT REFERENCES searches(id),
  text          TEXT NOT NULL,
  sentiment     INTEGER NOT NULL DEFAULT 0, -- 1 good, -1 bad, 0 neutral
  author        TEXT NOT NULL,             -- user id or 'agent'
  created_at    TEXT NOT NULL
);

CREATE TABLE places (
  id            TEXT PRIMARY KEY,          -- 'pl_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  source        TEXT NOT NULL DEFAULT 'manual', -- google_list | my_maps | google_place | manual
  list_name     TEXT,                      -- the list / layer name (never the author)
  name          TEXT NOT NULL,
  type          TEXT NOT NULL DEFAULT 'other', -- pack type (beach, surf, coffee, food, ...) | nightlife | construction | other
  tier          INTEGER NOT NULL DEFAULT 2, -- 1 top, 2 good, 3 ordinary
  note          TEXT,
  address       TEXT,
  lat           REAL NOT NULL,
  lng           REAL NOT NULL,
  area          TEXT,                      -- districts.yaml area id | 'trip'
  url           TEXT,
  ext_key       TEXT,                      -- dedupe key from the importer (e.g. name + rounded point)
  hidden        INTEGER NOT NULL DEFAULT 0,
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE price_history (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  price         INTEGER NOT NULL,
  currency      TEXT,
  source        TEXT,
  at            TEXT NOT NULL
);

CREATE TABLE profiles (
  user_id       TEXT PRIMARY KEY REFERENCES users(id),
  data          TEXT NOT NULL,             -- JSON, see core/profile.schema.json
  updated_at    TEXT NOT NULL
);

CREATE TABLE ratings (
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  user_id       TEXT NOT NULL REFERENCES users(id),
  overall       INTEGER NOT NULL,          -- general impression
  area          INTEGER NOT NULL,          -- area and road
  inside        INTEGER NOT NULL,          -- the house inside
  quiet         INTEGER NOT NULL,          -- quiet and neighbours
  note          TEXT,
  voice         TEXT,
  at            TEXT NOT NULL,
  PRIMARY KEY (listing_id, user_id)
);

CREATE TABLE relet_leads (
  id            TEXT PRIMARY KEY,          -- 'rl_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  contact_id    TEXT REFERENCES contacts(id),
  name          TEXT NOT NULL,
  channel       TEXT,
  address       TEXT,
  note          TEXT,
  status        TEXT NOT NULL DEFAULT 'new', -- new | reply | viewing | agreed | not_suitable
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE relets (
  search_id     TEXT PRIMARY KEY REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  date_from     TEXT,
  date_to       TEXT,
  price         INTEGER,
  currency      TEXT,
  consent       TEXT NOT NULL DEFAULT 'unknown', -- yes | asked | no | unknown
  consent_note  TEXT,
  ad_text       TEXT,
  photos        TEXT,                      -- JSON [photo ref] (same shape as listings.photos)
  channels      TEXT,                      -- JSON [{kind, label, count?, url?}]
  status        TEXT NOT NULL DEFAULT 'draft', -- draft | posted | found | closed
  updated_at    TEXT NOT NULL
);

CREATE TABLE renewal_votes (
  renewal_id    TEXT NOT NULL REFERENCES renewals(id),
  user_id       TEXT NOT NULL REFERENCES users(id),
  choice        TEXT NOT NULL,
  at            TEXT NOT NULL,
  PRIMARY KEY (renewal_id, user_id)
);

CREATE TABLE renewals (
  id            TEXT PRIMARY KEY,          -- 'rn_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  lease_to      TEXT NOT NULL,             -- YYYY-MM-DD
  status        TEXT NOT NULL DEFAULT 'open', -- open | decided
  choice        TEXT,                      -- stay | new | leave
  decided_how   TEXT,                      -- majority | owner
  note          TEXT,                      -- the agent's line ("only a new direct contract with Made")
  new_search_id TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  decided_at    TEXT,
  UNIQUE (search_id, lease_to)
);

CREATE TABLE scans (
  id            TEXT PRIMARY KEY,          -- 'sc_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT REFERENCES listings(id),
  bike_id       TEXT REFERENCES bikes(id),
  room          TEXT NOT NULL,
  phase         TEXT NOT NULL DEFAULT 'movein', -- movein | moveout | bike
  status        TEXT NOT NULL DEFAULT 'ok',     -- ok | redo | todo
  note          TEXT,
  doc_id        TEXT REFERENCES documents(id),
  app           TEXT,                      -- Scaniverse | Polycam | …
  sort          INTEGER NOT NULL DEFAULT 0,
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE searches (
  id            TEXT PRIMARY KEY,          -- 's_' + random
  owner_id      TEXT NOT NULL REFERENCES users(id),
  title         TEXT NOT NULL,             -- "Bukit, Nov 2026"
  region        TEXT NOT NULL,             -- pack path: 'bali/bukit', 'th/phuket'
  brief         TEXT NOT NULL,             -- JSON, see core/brief.schema.json
  status        TEXT NOT NULL DEFAULT 'active', -- active | paused | found | closed
  tg_chat_id    INTEGER,                   -- search group chat where cards are posted
  approval_mode TEXT NOT NULL DEFAULT 'ask',    -- ask | routine_auto
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, shares TEXT, rooms TEXT, money_mode TEXT NOT NULL DEFAULT 'split', dir_groups TEXT, agent_seen_at TEXT, stage TEXT, stage_manual TEXT, stage_changed_at TEXT, stage_history TEXT, home_listing_id TEXT, closed_at TEXT, agent_client TEXT, agent_version TEXT);

CREATE TABLE sent_marks (
  key           TEXT PRIMARY KEY,
  at            TEXT NOT NULL
);

CREATE TABLE server_state (
  key        TEXT PRIMARY KEY,               -- 'update' = {latest, checked_at, notified}
  value      TEXT NOT NULL,                  -- JSON
  updated_at TEXT NOT NULL
);

CREATE TABLE settlements (
  id            TEXT PRIMARY KEY,          -- 'st_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  from_user     TEXT NOT NULL REFERENCES users(id),
  to_user       TEXT NOT NULL REFERENCES users(id),
  amount        INTEGER NOT NULL,
  currency      TEXT NOT NULL,
  note          TEXT,
  created_by    TEXT NOT NULL,
  at            TEXT NOT NULL
);

CREATE TABLE share_reviews (
  id          TEXT PRIMARY KEY,                -- proposal id in the registry
  seen        TEXT NOT NULL,                   -- its updated_at when the card was sent
  at          TEXT NOT NULL
);

CREATE TABLE site_checks (
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  viewing_id    TEXT NOT NULL DEFAULT '',  -- '' when there is no viewing row
  user_id       TEXT NOT NULL REFERENCES users(id),
  item          TEXT NOT NULL,
  ok            INTEGER,                   -- 1 ok, 0 not ok, NULL unset
  note          TEXT,
  at            TEXT NOT NULL,
  PRIMARY KEY (listing_id, viewing_id, user_id, item)
);

CREATE TABLE site_photos (
  key           TEXT PRIMARY KEY,
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  viewing_id    TEXT NOT NULL DEFAULT '',
  user_id       TEXT NOT NULL REFERENCES users(id),
  at            TEXT NOT NULL
);

CREATE TABLE supplier_items (
  id            TEXT PRIMARY KEY,              -- 'si_' + random
  supplier_id   TEXT NOT NULL REFERENCES suppliers(id),
  name_id       TEXT NOT NULL,                 -- the name as in the supplier's list (what the message says); import key
  name_ru       TEXT NOT NULL,
  name_en       TEXT NOT NULL,
  grp           TEXT NOT NULL DEFAULT 'other',
  unit          TEXT NOT NULL DEFAULT 'kg',    -- kg | pcs | pack | bunch | 30pcs
  step          REAL NOT NULL DEFAULT 1,       -- 0.5 for kg, 1 for pieces
  price         INTEGER,                       -- per unit, main currency units; NULL = we ask
  price_unsure  INTEGER NOT NULL DEFAULT 0,    -- 1 = the source looks wrong, "уточнить"
  by_request    INTEGER NOT NULL DEFAULT 0,
  price_at      TEXT,                          -- YYYY-MM-DD of the list
  toy           TEXT,                          -- /goods/<toy>-192.webp
  top           INTEGER,                       -- 1..8 = the big toys until there are favourites
  fav           INTEGER NOT NULL DEFAULT 0,    -- how many delivered orders had it ("ваше обычное" from 2)
  sort          INTEGER NOT NULL DEFAULT 0,
  hidden        INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  UNIQUE (supplier_id, name_id)
);

CREATE TABLE supplier_prices (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  item_id       TEXT NOT NULL REFERENCES supplier_items(id),
  old_price     INTEGER,
  new_price     INTEGER,
  at            TEXT NOT NULL
);

CREATE TABLE suppliers (
  id                TEXT PRIMARY KEY,          -- 'su_' + random
  search_id         TEXT NOT NULL REFERENCES searches(id),
  dir_entry_id      TEXT,                      -- directory(id): the contact card gets "Заказать"
  name              TEXT NOT NULL,
  kind              TEXT NOT NULL DEFAULT 'other', -- fruit | fish | other (pill label, screen tone)
  channel           TEXT,                      -- whatsapp | telegram | phone
  address           TEXT,                      -- number or @handle
  hours             TEXT,                      -- 'HH:MM-HH:MM' local, NULL = not known
  min_free_delivery INTEGER,                   -- main units; NULL = no free delivery known
  delivery_note_ru  TEXT,
  delivery_note_en  TEXT,
  note_ru           TEXT,                      -- "Цены идут за рынком"
  note_en           TEXT,
  lang              TEXT NOT NULL DEFAULT 'id',
  currency          TEXT NOT NULL DEFAULT 'IDR',
  sort              INTEGER NOT NULL DEFAULT 0,
  hidden            INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
, delivery_fee INTEGER);

CREATE TABLE surf_cache (
  spot_id       TEXT PRIMARY KEY,
  lat           REAL NOT NULL,
  lng           REAL NOT NULL,
  fetched_at    TEXT NOT NULL,
  hourly        TEXT NOT NULL              -- JSON {time:[local 'YYYY-MM-DDTHH:00'], h:[m], p:[s], wd:[deg], ws:[km/h], wdir:[deg]}
);

CREATE TABLE threads (
  search_id     TEXT NOT NULL REFERENCES searches(id),
  contact_id    TEXT NOT NULL REFERENCES contacts(id),
  listing_id    TEXT REFERENCES listings(id),
  state         TEXT NOT NULL DEFAULT 'waiting_them', -- waiting_us | waiting_them | closed
  known         TEXT,                      -- facts agreed, 1-3 short lines
  open          TEXT,                      -- open questions, 1-3 short lines
  last          TEXT,                      -- one line about the last message
  last_at       TEXT,                      -- when the last message was sent or received
  updated_at    TEXT NOT NULL,
  PRIMARY KEY (search_id, contact_id)
);

CREATE TABLE tokens (
  hash          TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id),
  label         TEXT,
  created_at    TEXT NOT NULL
, revoked_at TEXT);

CREATE TABLE useful_links (
  id            TEXT PRIMARY KEY,          -- 'ul_' + random
  country       TEXT NOT NULL,             -- pack country: bali | kz | th
  city          TEXT,                      -- sub-pack slug or NULL for the whole country
  pack_id       TEXT,                      -- id of a useful.yaml item this row annotates (activity / last_checked), else NULL
  category      TEXT NOT NULL DEFAULT 'other', -- chats_rent | flea | bikes | news | visas | medicine | food | apps | guides | maps | other
  kind          TEXT NOT NULL DEFAULT 'web',   -- telegram | app | web | hunt
  name          TEXT NOT NULL,
  url           TEXT NOT NULL,
  about_ru      TEXT,
  about_en      TEXT,
  lang          TEXT,                      -- ru | en | id | th | kk | multi
  activity      TEXT,                      -- JSON {members?, per_day?, at} filled by the agent (read-only Telegram stats)
  last_checked  TEXT,                      -- YYYY-MM-DD
  status        TEXT NOT NULL DEFAULT 'pending', -- pending | approved | rejected
  suggested_by  TEXT REFERENCES users(id),
  search_id     TEXT REFERENCES searches(id), -- where it was suggested (the approver sees it in that search's digest)
  decided_by    TEXT,                      -- user id or 'agent'
  note          TEXT,                      -- the suggester's "why"
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, shared INTEGER NOT NULL DEFAULT 0);

CREATE TABLE users (
  id            TEXT PRIMARY KEY,          -- 'u_' + random
  tg_user_id    INTEGER UNIQUE,            -- Telegram numeric id (set when the person opens the bot)
  tg_username   TEXT,
  display_name  TEXT NOT NULL,
  lang          TEXT NOT NULL DEFAULT 'en',-- UI language for bot and Mini App
  created_at    TEXT NOT NULL
, link_gen INTEGER NOT NULL DEFAULT 0);

CREATE TABLE viewings (
  id            TEXT PRIMARY KEY,          -- 'v_' + random
  search_id     TEXT NOT NULL REFERENCES searches(id),
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  starts_at     TEXT NOT NULL,             -- local time with offset: '2026-11-18T10:00:00+08:00'
  status        TEXT NOT NULL DEFAULT 'proposed', -- proposed | confirmed | done | cancelled
  meet_note     TEXT,                      -- "front office at villa 2", "current tenants will meet"
  outcome       TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
, reminded_at TEXT, rate_asked_at TEXT);

CREATE TABLE votes (
  listing_id    TEXT NOT NULL REFERENCES listings(id),
  user_id       TEXT NOT NULL REFERENCES users(id),
  decision      TEXT NOT NULL,
  comment       TEXT,
  at            TEXT NOT NULL,
  PRIMARY KEY (listing_id, user_id)
);

CREATE TABLE web_logins (
  id          TEXT PRIMARY KEY,        -- public part: goes to the bot link or the one-time link
  kind        TEXT NOT NULL,           -- bot (number match) | link (one-time link from /web)
  secret_hash TEXT NOT NULL,           -- the browser's secret (bot) or the link's code (link)
  number      INTEGER,                 -- the number the site shows
  options     TEXT,                    -- JSON [n, n, n] offered in the bot
  device      TEXT,                    -- "Chrome, macOS · ID"
  status      TEXT NOT NULL,           -- new | asked | approved | denied | done
  user_id     TEXT REFERENCES users(id),
  expires_at  TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE web_sessions (
  hash        TEXT PRIMARY KEY,        -- sha256 of the cookie
  id          TEXT NOT NULL UNIQUE,    -- shown to the person, to end one session
  user_id     TEXT NOT NULL REFERENCES users(id),
  device      TEXT,
  created_at  TEXT NOT NULL,
  last_at     TEXT NOT NULL,
  expires_at  TEXT NOT NULL
);

CREATE UNIQUE INDEX access_conn ON access(tg_conn) WHERE tg_conn IS NOT NULL;

CREATE INDEX access_peers_chat ON access_peers(user_id, chat_id);

CREATE INDEX access_receipts_user ON access_receipts(user_id, at);

CREATE INDEX afisha_country ON afisha(country, status, starts_at);

CREATE INDEX ai_usage_search ON ai_usage(search_id);

CREATE INDEX bikes_search ON bikes(search_id, status);

CREATE INDEX contact_channels_address ON contact_channels(address, channel);

CREATE INDEX contacts_owner ON contacts(owner_id);

CREATE INDEX deal_terms_search ON deal_terms(search_id, seq);

CREATE INDEX directory_search ON directory(search_id, grp, sort);

CREATE INDEX documents_listing ON documents(listing_id, kind);

CREATE INDEX dossier_items_d ON dossier_items(dossier_id, created_at);

CREATE INDEX dossiers_owner ON dossiers(owner_identity);

CREATE INDEX dossiers_owner_id ON dossiers(owner_id);

CREATE INDEX drafts_status ON drafts(search_id, status);

CREATE INDEX event_bookings_search ON event_bookings(search_id, status, starts_at);

CREATE INDEX event_feedback_rating ON event_feedback(rating, updated_at);

CREATE INDEX event_feedback_search ON event_feedback(search_id, updated_at);

CREATE INDEX events_search ON events(search_id, id);

CREATE INDEX events_search_kind ON events(search_id, kind, id);

CREATE UNIQUE INDEX expenses_order ON expenses(order_id) WHERE order_id IS NOT NULL;

CREATE INDEX expenses_search ON expenses(search_id, date);

CREATE INDEX guests_user ON guests(user_id, status);

CREATE INDEX house_contacts_search ON house_contacts(search_id, sort);

CREATE INDEX issues_search ON issues(search_id, status);

CREATE INDEX items_search ON items(search_id, status);

CREATE INDEX listings_search ON listings(search_id, status);

CREATE INDEX messages_contact ON messages(contact_id, at);

CREATE INDEX messages_listing ON messages(listing_id, at);

CREATE INDEX messages_search ON messages(search_id, direction, at);

CREATE INDEX meter_readings_search ON meter_readings(search_id, at);

CREATE UNIQUE INDEX order_sets_name ON order_sets(search_id, name_key);

CREATE INDEX order_sets_repeat ON order_sets(repeat) WHERE repeat != 'none';

CREATE UNIQUE INDEX orders_basket ON orders(supplier_id) WHERE status='basket';

CREATE INDEX orders_search ON orders(search_id, status, updated_at);

CREATE INDEX pack_shares_user ON pack_shares(user_id, created_at);

CREATE INDEX parties_search ON parties(search_id, starts_at);

CREATE INDEX parties_token ON parties(token_hash);

CREATE INDEX party_guests_party ON party_guests(party_id);

CREATE UNIQUE INDEX party_guests_secret ON party_guests(secret_hash);

CREATE INDEX party_items_party ON party_items(party_id, sort);

CREATE INDEX people_notes_contact ON people_notes(contact_id);

CREATE INDEX people_notes_identity ON people_notes(identity);

CREATE UNIQUE INDEX places_ext ON places(search_id, ext_key);

CREATE INDEX places_search ON places(search_id, area);

CREATE INDEX price_history_listing ON price_history(listing_id, at);

CREATE INDEX relet_leads_search ON relet_leads(search_id, updated_at);

CREATE INDEX scans_search ON scans(search_id, phase);

CREATE INDEX settlements_search ON settlements(search_id, at);

CREATE INDEX site_photos_listing ON site_photos(listing_id);

CREATE INDEX supplier_prices_item ON supplier_prices(item_id, id);

CREATE INDEX suppliers_search ON suppliers(search_id, sort);

CREATE INDEX threads_state ON threads(search_id, state, last_at);

CREATE INDEX useful_links_country ON useful_links(country, status);

CREATE INDEX viewings_search ON viewings(search_id, starts_at);

CREATE INDEX web_sessions_user ON web_sessions(user_id);
